"""Run an isolated PageIndex-vs-local retrieval A/B smoke.

This is an eval-only adapter layer. It does not call PageIndex live agents,
does not mutate DB state, and does not build or alter production indexes.

The default comparison is intentionally labelled as a lexical proxy:

* baseline: the current project's ``embedding_text`` surface from
  ``rag_chunks.jsonl`` for the same canary chunk set.
* candidate: the PageIndex markdown tree leaf surface generated by
  ``scripts.pageindex_ab_scaffold``.

This proves the identity mapping and A/B report plumbing before any paid/API
PageIndex reasoning call is introduced.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Mapping, Sequence


AI_WORKER_ROOT = Path(__file__).resolve().parents[1]
REPO_ROOT = AI_WORKER_ROOT.parent
if str(AI_WORKER_ROOT) not in sys.path:
    sys.path.insert(0, str(AI_WORKER_ROOT))

from app.capabilities.rag.generation import RetrievedChunk  # noqa: E402
from eval.harness.bm25_retriever import (  # noqa: E402
    BM25EvalRetriever,
    build_bm25_index,
)
from eval.harness.embedding_text_builder import (  # noqa: E402
    VARIANT_RAW,
    VARIANT_TITLE_SECTION,
)
from eval.harness.v4_ab_eval import (  # noqa: E402
    QueryRecord,
    run_paired_ab,
    write_ab_outputs,
)


DEFAULT_RUN_DIR = AI_WORKER_ROOT / "eval" / "reports" / "pageindex-ab" / "canary_smoke"
COMMENT_RE = re.compile(r"<!--\s*pageindex_ab\s+({.*?})\s*-->", re.DOTALL)
MARKDOWN_HEADING_RE = re.compile(r"^#{1,6}\s*", re.MULTILINE)


@dataclass(frozen=True)
class SurfaceRecord:
    chunk_id: str
    doc_id: str
    section: str
    text: str
    title: str = ""
    section_id: str = ""
    node_id: str = ""
    line_num: int | None = None
    metadata: dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class _BM25Chunk:
    chunk_id: str
    doc_id: str
    section: str
    text: str
    title: str = ""


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    run_dir = Path(args.run_dir)
    manifest_path = run_dir / "manifest.json"
    structure_path = run_dir / "pageindex_structure.json"
    queries_path = run_dir / "selected_queries.jsonl"
    output_dir = Path(args.output_dir) if args.output_dir else run_dir / "ab_offline"

    manifest = read_json(manifest_path)
    queries = load_queries(queries_path)
    pageindex_records = flatten_pageindex_tree(read_json(structure_path))
    selected_chunk_ids = [record.chunk_id for record in pageindex_records]
    corpus = load_corpus(resolve_manifest_path(manifest, "corpus"))
    baseline_records = build_baseline_records(corpus, selected_chunk_ids)

    baseline_name = "local_embedding_text_bm25_proxy"
    candidate_name = "pageindex_tree_bm25_proxy"
    baseline = make_bm25_retriever(
        baseline_records,
        name=baseline_name,
        top_k=args.top_k,
        variant=VARIANT_RAW,
    )
    candidate = make_bm25_retriever(
        pageindex_records,
        name=candidate_name,
        top_k=args.top_k,
        variant=VARIANT_TITLE_SECTION,
    )

    result = run_paired_ab(
        queries,
        baseline_retriever=baseline,
        candidate_retriever=candidate,
        baseline_variant=baseline_name,
        candidate_variant=candidate_name,
        progress_log_every=0,
    )
    result.aggregate.update({
        "evaluation_mode": "offline_lexical_adapter_smoke",
        "source_run_dir": repo_relative(run_dir),
        "pageindex_structure": repo_relative(structure_path),
        "query_source": repo_relative(queries_path),
        "baseline_note": (
            "BM25 proxy over current-project embedding_text for the canary "
            "chunk set; this is not a live dense/vector RAG run."
        ),
        "candidate_note": (
            "BM25 proxy over PageIndex markdown tree leaves; this is not a "
            "live PageIndex reasoning-agent run."
        ),
    })
    paths = write_ab_outputs(
        result,
        out_dir=output_dir,
        baseline_variant=baseline_name,
        candidate_variant=candidate_name,
    )
    write_json(
        output_dir / "pageindex_ab_eval_manifest.json",
        {
            "evaluation_mode": result.aggregate["evaluation_mode"],
            "run_dir": repo_relative(run_dir),
            "outputs": {key: repo_relative(path) for key, path in paths.items()},
            "query_count": len(queries),
            "pageindex_record_count": len(pageindex_records),
            "baseline_record_count": len(baseline_records),
            "top_k": int(args.top_k),
            "caveat": (
                "Use this as adapter/report plumbing proof. Replace the BM25 "
                "candidate with cached/live PageIndex agent selections before "
                "claiming PageIndex retrieval quality."
            ),
        },
    )
    print(json.dumps({
        "output_dir": repo_relative(output_dir),
        "query_count": len(queries),
        "pageindex_record_count": len(pageindex_records),
        "baseline_record_count": len(baseline_records),
        "summary_json": repo_relative(paths["summary_json"]),
        "summary_md": repo_relative(paths["summary_md"]),
        "per_query": repo_relative(paths["per_query"]),
    }, ensure_ascii=False, indent=2))
    return 0


def parse_args(argv: list[str] | None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--run-dir", type=Path, default=DEFAULT_RUN_DIR)
    parser.add_argument("--output-dir", type=Path, default=None)
    parser.add_argument("--top-k", type=int, default=10)
    return parser.parse_args(argv)


def make_bm25_retriever(
    records: Sequence[SurfaceRecord],
    *,
    name: str,
    top_k: int,
    variant: str,
) -> BM25EvalRetriever:
    chunks = [
        _BM25Chunk(
            chunk_id=record.chunk_id,
            doc_id=record.doc_id,
            section=record.section,
            text=record.text,
            title=record.title,
        )
        for record in records
    ]
    index = build_bm25_index(chunks, embedding_text_variant=variant)
    return BM25EvalRetriever(index, top_k=top_k, name=name, index_version=name)


def load_queries(path: Path) -> list[QueryRecord]:
    rows = read_jsonl(path)
    out: list[QueryRecord] = []
    for row in rows:
        expected_page_ids = [str(x) for x in row.get("expected_page_ids") or [] if str(x)]
        out.append(QueryRecord(
            qid=str(row.get("query_id") or row.get("id") or ""),
            query=str(row.get("query") or ""),
            expected_doc_ids=tuple(expected_page_ids),
            answer_type=str(row.get("answer_type") or ""),
            difficulty=str(row.get("difficulty") or ""),
            bucket=str(row.get("bucket") or ""),
            v4_meta={
                "expected_section_ids": row.get("expected_section_ids") or [],
                "expected_chunk_ids": row.get("expected_chunk_ids") or [],
                "label_status": row.get("label_status"),
            },
        ))
    if not out:
        raise ValueError(f"No queries found in {path}")
    return out


def flatten_pageindex_tree(tree_payload: Mapping[str, Any]) -> list[SurfaceRecord]:
    records: list[SurfaceRecord] = []

    def walk(nodes: Sequence[Mapping[str, Any]], parents: list[str]) -> None:
        for node in nodes:
            title = str(node.get("title") or "")
            text = str(node.get("text") or "")
            meta = extract_comment_metadata(text)
            next_parents = [*parents, title]
            if meta.get("chunk_id"):
                records.append(SurfaceRecord(
                    chunk_id=str(meta.get("chunk_id") or ""),
                    doc_id=str(meta.get("doc_id") or ""),
                    section=title.removeprefix("Section: ").strip(),
                    text=strip_pageindex_markup(text),
                    title=document_title_from_path(next_parents),
                    section_id=str(meta.get("section_id") or ""),
                    node_id=str(node.get("node_id") or ""),
                    line_num=to_int(node.get("line_num")),
                    metadata=dict(meta),
                ))
            children = node.get("nodes") or []
            if isinstance(children, list):
                walk(children, next_parents)

    roots = tree_payload.get("structure") or []
    if not isinstance(roots, list):
        raise ValueError("PageIndex structure must contain a list field named 'structure'")
    walk(roots, [])
    if not records:
        raise ValueError("No PageIndex chunk metadata comments found in tree")
    return records


def build_baseline_records(
    corpus: Mapping[str, Mapping[str, Any]],
    selected_chunk_ids: Sequence[str],
) -> list[SurfaceRecord]:
    out: list[SurfaceRecord] = []
    for chunk_id in selected_chunk_ids:
        row = corpus.get(chunk_id)
        if not row:
            continue
        section_path = row.get("section_path") or []
        if isinstance(section_path, list):
            section = " > ".join(str(part) for part in section_path if str(part).strip())
        else:
            section = str(section_path or "")
        text = str(row.get("embedding_text") or row.get("chunk_text") or "")
        out.append(SurfaceRecord(
            chunk_id=str(row.get("chunk_id") or ""),
            doc_id=str(row.get("doc_id") or ""),
            section=section,
            text=text,
            title=str(row.get("retrieval_title") or row.get("display_title") or row.get("title") or ""),
            section_id=str(row.get("section_id") or ""),
            metadata={
                "section_key": row.get("section_key"),
                "section_type": row.get("section_type"),
                "surface": "rag_chunks.embedding_text",
            },
        ))
    if len(out) != len(selected_chunk_ids):
        missing = sorted(set(selected_chunk_ids) - {record.chunk_id for record in out})
        raise ValueError(f"Selected chunk ids missing from corpus: {missing[:10]}")
    return out


def extract_comment_metadata(text: str) -> dict[str, Any]:
    match = COMMENT_RE.search(text or "")
    if not match:
        return {}
    payload = json.loads(match.group(1))
    return payload if isinstance(payload, dict) else {}


def strip_pageindex_markup(text: str) -> str:
    stripped = COMMENT_RE.sub("", text or "")
    stripped = MARKDOWN_HEADING_RE.sub("", stripped)
    return stripped.strip()


def document_title_from_path(path_titles: Sequence[str]) -> str:
    for title in reversed(path_titles):
        if title.startswith("Document: "):
            return title.removeprefix("Document: ").strip()
    return ""


def resolve_manifest_path(manifest: Mapping[str, Any], key: str) -> Path:
    inputs = manifest.get("inputs")
    if not isinstance(inputs, Mapping) or key not in inputs:
        raise ValueError(f"manifest.inputs.{key} is missing")
    path = Path(str(inputs[key]))
    return path if path.is_absolute() else REPO_ROOT / path


def load_corpus(path: Path) -> dict[str, dict[str, Any]]:
    out: dict[str, dict[str, Any]] = {}
    for row in read_jsonl(path):
        chunk_id = str(row.get("chunk_id") or "")
        if chunk_id:
            out[chunk_id] = row
    if not out:
        raise ValueError(f"No chunks found in {path}")
    return out


def read_json(path: Path) -> dict[str, Any]:
    payload = json.loads(path.read_text(encoding="utf-8-sig"))
    if not isinstance(payload, dict):
        raise ValueError(f"{path} must contain a JSON object")
    return payload


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    with path.open("r", encoding="utf-8-sig") as handle:
        for line_number, line in enumerate(handle, start=1):
            if not line.strip():
                continue
            payload = json.loads(line)
            if not isinstance(payload, dict):
                raise ValueError(f"{path}: line {line_number} must be a JSON object")
            rows.append(payload)
    return rows


def write_json(path: Path, payload: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def to_int(value: Any) -> int | None:
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def repo_relative(path: Path) -> str:
    try:
        return str(Path(path).resolve().relative_to(REPO_ROOT.resolve())).replace("\\", "/")
    except ValueError:
        return str(path)


if __name__ == "__main__":
    raise SystemExit(main())
